window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b83199f416373995"]={"versions": [{"id": "FIG-b83199f416373995", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherlayout-Diagramm zur logischen Adressierung und Organisation der optionalen ROM-Blöcke innerhalb eines Dataset-NVRAM-Blocks (AUTOSAR Basic Software Modul NVM / NVRAM Manager). Es verdeutlicht die logische Indizierung der ROM-Datenbereiche im Anschluss an die NV-Blöcke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erstes optionales ROM-Block-Datenelement für den Datensatz mit Startindex <code>NVM_NV_BLOCK_NUM</code>.\n</li><li><strong>Drei Punkte (<code>...</code>)</strong>: Vertikale Auslassungspunkte zur Repräsentation dazwischenliegender ROM-Block-Datenelemente.\n</li><li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letztes optionales ROM-Block-Datenelement für den Datensatz mit dem Maximalindex <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code>.\n</li><li><strong>Vertikale Index-Achse / Maßpfeil</strong>: Pfeil zur Kennzeichnung des gültigen Adressierungsbereichs <code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>.\n</li><li><strong>Gestrichelter Rahmen</strong>: Logische Gruppierung der optionalen ROM-Block-Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Diagramm ohne Sequenzfluss. Die logische Auswahl eines ROM-Blocks erfolgt über den NvM-Datensatz-Index (<code>DatasetIndex</code>), wenn dieser innerhalb des Bereichs von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> liegt, um bei Lesezugriffen Standard- bzw. ROM-Daten anstelle von persistenten NV-Speicherdaten bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die logische Indexzuordnung (<code>DatasetIndex</code>) und nicht das physische NV-Speicherlayout. Entwickler müssen bei der Konfiguration (<code>NvMBlockDescriptor</code>) beachten, dass ROM-Blöcke optional sind (<code>opt</code>) und bei Vorhandensein lückenlos über Indizes adressiert werden, die direkt an die Anzahl der NV-Blöcke (<code>NVM_NV_BLOCK_NUM</code>) anschließen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94b9a7c5c7a6b2e9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherlayout-Diagramm zur logischen Adressierung und Organisation der optionalen ROM-Blöcke innerhalb eines Dataset-NVRAM-Blocks (AUTOSAR Basic Software Modul NVM / NVRAM Manager). Es verdeutlicht die logische Indizierung der ROM-Datenbereiche im Anschluss an die NV-Blöcke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erstes optionales ROM-Block-Datenelement für den Datensatz mit Startindex <code>NVM_NV_BLOCK_NUM</code>.\n</li><li><strong>Drei Punkte (<code>...</code>)</strong>: Vertikale Auslassungspunkte zur Repräsentation dazwischenliegender ROM-Block-Datenelemente.\n</li><li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letztes optionales ROM-Block-Datenelement für den Datensatz mit dem Maximalindex <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code>.\n</li><li><strong>Vertikale Index-Achse / Maßpfeil</strong>: Pfeil zur Kennzeichnung des gültigen Adressierungsbereichs <code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>.\n</li><li><strong>Gestrichelter Rahmen</strong>: Logische Gruppierung der optionalen ROM-Block-Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Diagramm ohne Sequenzfluss. Die logische Auswahl eines ROM-Blocks erfolgt über den NvM-Datensatz-Index (<code>DatasetIndex</code>), wenn dieser innerhalb des Bereichs von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> liegt, um bei Lesezugriffen Standard- bzw. ROM-Daten anstelle von persistenten NV-Speicherdaten bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die logische Indexzuordnung (<code>DatasetIndex</code>) und nicht das physische NV-Speicherlayout. Entwickler müssen bei der Konfiguration (<code>NvMBlockDescriptor</code>) beachten, dass ROM-Blöcke optional sind (<code>opt</code>) und bei Vorhandensein lückenlos über Indizes adressiert werden, die direkt an die Anzahl der NV-Blöcke (<code>NVM_NV_BLOCK_NUM</code>) anschließen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d865c95f7c8dfeb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherlayout-Diagramm zur logischen Adressierung und Organisation der optionalen ROM-Blöcke innerhalb eines Dataset-NVRAM-Blocks (AUTOSAR Basic Software Modul NVM / NVRAM Manager). Es verdeutlicht die logische Indizierung der ROM-Datenbereiche im Anschluss an die NV-Blöcke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erstes optionales ROM-Block-Datenelement für den Datensatz mit Startindex <code>NVM_NV_BLOCK_NUM</code>.\n</li><li><strong>Drei Punkte (<code>...</code>)</strong>: Vertikale Auslassungspunkte zur Repräsentation dazwischenliegender ROM-Block-Datenelemente.\n</li><li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letztes optionales ROM-Block-Datenelement für den Datensatz mit dem Maximalindex <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code>.\n</li><li><strong>Vertikale Index-Achse / Maßpfeil</strong>: Pfeil zur Kennzeichnung des gültigen Adressierungsbereichs <code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>.\n</li><li><strong>Gestrichelter Rahmen</strong>: Logische Gruppierung der optionalen ROM-Block-Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Diagramm ohne Sequenzfluss. Die logische Auswahl eines ROM-Blocks erfolgt über den NvM-Datensatz-Index (<code>DatasetIndex</code>), wenn dieser innerhalb des Bereichs von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> liegt, um bei Lesezugriffen Standard- bzw. ROM-Daten anstelle von persistenten NV-Speicherdaten bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die logische Indexzuordnung (<code>DatasetIndex</code>) und nicht das physische NV-Speicherlayout. Entwickler müssen bei der Konfiguration (<code>NvMBlockDescriptor</code>) beachten, dass ROM-Blöcke optional sind (<code>opt</code>) und bei Vorhandensein lückenlos über Indizes adressiert werden, die direkt an die Anzahl der NV-Blöcke (<code>NVM_NV_BLOCK_NUM</code>) anschließen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-efcc8194513446c9", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherlayout-Diagramm zur logischen Adressierung und Organisation der optionalen ROM-Blöcke innerhalb eines Dataset-NVRAM-Blocks (AUTOSAR Basic Software Modul NVM / NVRAM Manager). Es verdeutlicht die logische Indizierung der ROM-Datenbereiche im Anschluss an die NV-Blöcke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erstes optionales ROM-Block-Datenelement für den Datensatz mit Startindex <code>NVM_NV_BLOCK_NUM</code>.\n</li><li><strong>Drei Punkte (<code>...</code>)</strong>: Vertikale Auslassungspunkte zur Repräsentation dazwischenliegender ROM-Block-Datenelemente.\n</li><li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letztes optionales ROM-Block-Datenelement für den Datensatz mit dem Maximalindex <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code>.\n</li><li><strong>Vertikale Index-Achse / Maßpfeil</strong>: Pfeil zur Kennzeichnung des gültigen Adressierungsbereichs <code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>.\n</li><li><strong>Gestrichelter Rahmen</strong>: Logische Gruppierung der optionalen ROM-Block-Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Diagramm ohne Sequenzfluss. Die logische Auswahl eines ROM-Blocks erfolgt über den NvM-Datensatz-Index (<code>DatasetIndex</code>), wenn dieser innerhalb des Bereichs von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> liegt, um bei Lesezugriffen Standard- bzw. ROM-Daten anstelle von persistenten NV-Speicherdaten bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die logische Indexzuordnung (<code>DatasetIndex</code>) und nicht das physische NV-Speicherlayout. Entwickler müssen bei der Konfiguration (<code>NvMBlockDescriptor</code>) beachten, dass ROM-Blöcke optional sind (<code>opt</code>) und bei Vorhandensein lückenlos über Indizes adressiert werden, die direkt an die Anzahl der NV-Blöcke (<code>NVM_NV_BLOCK_NUM</code>) anschließen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-72a30e7f1a7723c2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Speicherlayout-Diagramm zur logischen Adressierung und Organisation der optionalen ROM-Blöcke innerhalb eines Dataset-NVRAM-Blocks (AUTOSAR Basic Software Modul NVM / NVRAM Manager). Es verdeutlicht die logische Indizierung der ROM-Datenbereiche im Anschluss an die NV-Blöcke.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erstes optionales ROM-Block-Datenelement für den Datensatz mit Startindex <code>NVM_NV_BLOCK_NUM</code>.\n</li><li><strong>Drei Punkte (<code>...</code>)</strong>: Vertikale Auslassungspunkte zur Repräsentation dazwischenliegender ROM-Block-Datenelemente.\n</li><li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letztes optionales ROM-Block-Datenelement für den Datensatz mit dem Maximalindex <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code>.\n</li><li><strong>Vertikale Index-Achse / Maßpfeil</strong>: Pfeil zur Kennzeichnung des gültigen Adressierungsbereichs <code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>.\n</li><li><strong>Gestrichelter Rahmen</strong>: Logische Gruppierung der optionalen ROM-Block-Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout-Diagramm ohne Sequenzfluss. Die logische Auswahl eines ROM-Blocks erfolgt über den NvM-Datensatz-Index (<code>DatasetIndex</code>), wenn dieser innerhalb des Bereichs von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> liegt, um bei Lesezugriffen Standard- bzw. ROM-Daten anstelle von persistenten NV-Speicherdaten bereitzustellen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die logische Indexzuordnung (<code>DatasetIndex</code>) und nicht das physische NV-Speicherlayout. Entwickler müssen bei der Konfiguration (<code>NvMBlockDescriptor</code>) beachten, dass ROM-Blöcke optional sind (<code>opt</code>) und bei Vorhandensein lückenlos über Indizes adressiert werden, die direkt an die Anzahl der NV-Blöcke (<code>NVM_NV_BLOCK_NUM</code>) anschließen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b83199f416373995", "to": "FIG-94b9a7c5c7a6b2e9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-94b9a7c5c7a6b2e9", "to": "FIG-5d865c95f7c8dfeb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d865c95f7c8dfeb", "to": "FIG-efcc8194513446c9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-efcc8194513446c9", "to": "FIG-72a30e7f1a7723c2", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
